import { describe, expect, it } from "vitest";
import { findFeatureScriptStructureError } from "../featurescriptstructure";

const HEADER = [
    "// Generated by Onshape Node Editor",
    "// Edits will be overwritten by the Onshape Node Editor app",
    "FeatureScript 2960;",
    'import(path : "onshape/std/common.fs", version : "2960.0");',
    "",
].join("\n");

const VALID_SOURCE = `${HEADER}export const myNewFeature = defineFeature(function(context is Context, id is Id, definition is map)
precondition
{
    annotation { "Property Function Name" : "entities" }
    entities is Query;
}
{
    fCylinder(context, id, {});
});
`;

describe("findFeatureScriptStructureError", () => {
    it("accepts a complete Define Feature / End Feature chain", () => {
        expect(findFeatureScriptStructureError(VALID_SOURCE)).toBeUndefined();
    });

    it("refuses the header plus orphan `});` the unwired default graph used to build", () => {
        const malformed = `${HEADER}});\n`;

        const error = findFeatureScriptStructureError(malformed);

        expect(error).toBeDefined();
        expect(error).toContain("structurally invalid");
        expect(error).toContain("Define Feature");
        expect(error).toContain("End Feature");
        expect(error).toContain("orphan `});` at line 5");
    });

    it("refuses a Define Feature that is never closed by an End Feature", () => {
        const malformed = VALID_SOURCE.slice(0, VALID_SOURCE.lastIndexOf("});\n"));

        const error = findFeatureScriptStructureError(malformed);

        expect(error).toContain("never closed");
        expect(error).toContain("End Feature");
    });

    it("ignores an indented `});` inside the feature body and group function bodies", () => {
        const source = `${HEADER}function groupOne(context is Context) {
    if (true)
    {
        });
    }
}
export const myNewFeature = defineFeature(function(context is Context, id is Id, definition is map)
{
    groupOne(context);
});
`;

        expect(findFeatureScriptStructureError(source)).toBeUndefined();
    });

    it("refuses a second top-level `});` with no matching Define Feature", () => {
        const malformed = VALID_SOURCE.replace("});\n", "});\n});\n");

        const error = findFeatureScriptStructureError(malformed);

        expect(error).toContain("orphan `});`");
        expect(error).toContain("Define Feature");
    });
});
